from collections import deque

def find_regions(grid):
    colors = set()
    for row in grid:
        for cell in row:
            colors.add(cell)
    return sorted(colors)

print(f"Unique colors: {find_regions(grid)}")

# Count occurrences and find bounding boxes
def find_bounding_boxes(grid, target_color):
    boxes = []
    for r, row in enumerate(grid):
        for c, val in enumerate(row):
            if val == target_color:
                box = {"pos": None, "color": target_color}
                for dr in range(-50, 50):
                    for dc in range(-50, 50):
                        r2, c2 = r + dr, c + dc
                        if 0 <= r2 < len(grid) and 0 <= c2 < len(grid[0]):
                            if grid[r2][c2] != target_color:
                                if box["pos"] is None:
                                    box["pos"] = (r2, c2)
                                break
                    else:
                        continue
                    break
                if box["pos"] is not None:
                    boxes.append(box)
    return boxes

# Find all connected components for each color
def get_components(grid, color):
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == color and (r, c) not in visited:
                comp = {
                    "color": color,
                    "cells": [],
                    "min_r": float('inf'), "max_r": 0,
                    "min_c": float('inf'), "max_c": 0,
                    "size": 0
                }
                visited.add((r, c))
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    comp["cells"].append((cr, cc))
                    comp["min_r"] = min(comp["min_r"], cr)
                    comp["max_r"] = max(comp["max_r"], cr)
                    comp["min_c"] = min(comp["min_c"], cc)
                    comp["max_c"] = max(comp["max_c"], cc)
                    comp["size"] += 1

                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
                components.append(comp)
    return components

